INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('059cf774-2cd3-5e78-99a1-6047b804fbfc', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 9, 9, 'A North American socket supplies 120 V r.m.s. What is the peak voltage?', NULL, 1, 'numeric'::answer_type, '169.7', 'V', false, NULL, false, NULL, 'V₀ = √2 × V_rms = √2 × 120 = 170 V. Mark scheme (2 marks). C1: V₀ = √2 V_rms. A1: V₀ = 170 V.', 2, NULL, NULL),
('bd5c1bc2-688b-5936-bbb2-eb2040dad36b', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 10, 10, 'Which relationship is correct for a sinusoidal alternating current?', NULL, 1, 'multiple_choice'::answer_type, 'I_rms = I₀/√2', NULL, false, NULL, false, NULL, 'For a sine wave the mean of I² is I₀²/2. Mark scheme (1 mark). B1: C (I_rms = I₀/√2).', 1, NULL, NULL),
('7877621f-7a19-5768-abd5-aa9676d08c77', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 11, 11, 'The current through a lamp varies sinusoidally with an amplitude of 2.4 A. Calculate the r.m.s. current.', NULL, 1, 'numeric'::answer_type, '1.697', 'A', false, NULL, false, NULL, 'I_rms = I₀/√2 = 2.4 ÷ √2 = 1.70 A. Mark scheme (2 marks). C1: I_rms = I₀/√2. A1: I_rms = 1.70 A.', 2, NULL, NULL),
('83dd3c91-0c46-57bf-a110-c1c208867820', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 12, 12, 'What is the mean value of a sinusoidal alternating current over one complete cycle?', NULL, 1, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'The positive and negative halves cancel. Mark scheme (1 mark). B1: A (Zero).', 1, NULL, NULL),
('a4e411a0-549d-53e3-a7a9-eb5bd6fbb384', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 13, 13, 'One complete cycle of an alternating supply lasts 16.7 ms. Calculate its frequency.', NULL, 1, 'numeric'::answer_type, '59.88', 'Hz', false, NULL, false, NULL, 'f = 1/T = 1 ÷ 16.7 × 10⁻³ = 59.9 Hz. Mark scheme (2 marks). C1: f = 1/T. A1: f = 59.9 Hz.', 2, NULL, NULL),
('0c9d06cb-52a1-5edd-b12a-c08568897db8', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 14, 14, 'Why is the r.m.s. value used to describe an alternating current, rather than its mean value?', NULL, 1, 'multiple_choice'::answer_type, 'The mean is zero, but the heating effect depends on I², which is always positive', NULL, false, NULL, false, NULL, 'The r.m.s. value gives the same heating as an equal steady current. Mark scheme (1 mark). B1: D (The mean is zero, but the heating effect depends on I², which is always positive).', 1, NULL, NULL),
('5225cac5-221a-529f-9505-c410f044d045', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 15, 15, 'A 46 Ω resistor is connected to a 230 V r.m.s. supply. Calculate the peak current.', NULL, 1, 'numeric'::answer_type, '7.071', 'A', false, NULL, false, NULL, 'I_rms = 230 ÷ 46 = 5.0 A. I₀ = √2 × 5.0 = 7.07 A. Mark scheme (2 marks). C1: I_rms then × √2. A1: I₀ = 7.07 A.', 2, NULL, NULL),
('5c1e1d60-4772-5a61-b678-b681c1022c87', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 16, 16, 'For a sinusoidal supply, what is (peak value) ÷ (r.m.s. value)?', NULL, 1, 'multiple_choice'::answer_type, '√2', NULL, false, NULL, false, NULL, 'For a sine wave V₀ = √2 V_rms, so the ratio is √2 ≈ 1.41. Mark scheme (1 mark). B1: B (√2).', 1, NULL, NULL),
('67c07985-960f-5848-982b-68660f4fa4ce', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 17, 17, 'A 50 Ω heater gives the same power on a steady current of 4.0 A as on a sinusoidal alternating current. Calculate the peak value of the alternating current.', NULL, 1, 'numeric'::answer_type, '5.657', 'A', false, NULL, false, NULL, 'The r.m.s. current equals the equivalent steady current, 4.0 A, so I₀ = √2 × 4.0 = 5.66 A. Mark scheme (2 marks). C1: I_rms = equivalent d.c. A1: I₀ = 5.66 A.', 2, NULL, NULL),
('03aec400-4130-5fc4-a3e0-62fdfb8e0612', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 18, 18, 'What is the unit of frequency?', NULL, 1, 'multiple_choice'::answer_type, 'Hz, equivalent to s⁻¹', NULL, false, NULL, false, NULL, 'Frequency is the number of cycles per second. Mark scheme (1 mark). B1: C (Hz, equivalent to s⁻¹).', 1, NULL, NULL),
('5cd20b14-9ea3-5883-811c-58e236e7a61a', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 19, 19, 'A sinusoidal supply has an r.m.s. voltage of 6.0 V. Calculate its peak-to-peak voltage.', NULL, 1, 'numeric'::answer_type, '16.97', 'V', false, NULL, false, NULL, 'V₀ = √2 × 6.0 = 8.49 V. Peak-to-peak = 2 × 8.485 = 17.0 V. Mark scheme (2 marks). C1: V₀ then × 2. A1: V_pp = 17.0 V.', 2, NULL, NULL),
('50d461cd-5db8-54f3-933c-b071033369f0', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 20, 20, 'A square-wave voltage switches between +V₀ and −V₀ with equal times at each. What is its r.m.s. value?', NULL, 1, 'multiple_choice'::answer_type, 'V₀', NULL, false, NULL, false, NULL, 'V² is always V₀², so the r.m.s. value is V₀. Mark scheme (1 mark). B1: A (V₀).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgcba5fb0f-t fgcba5fb0f-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgcba5fb0f-t">Square-wave voltage</title><desc id="fgcba5fb0f-d">Graph of voltage V against time t for a square wave: V is +V₀ for the first half of each period T and −V₀ for the second half. Two periods are shown.</desc><line x1="35.4" y1="138" x2="388" y2="138" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="35.4" y1="242" x2="35.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,138 385.7,141 385.7,135" style="fill:currentColor;stroke:none"/><polygon points="35.4,24 38.4,30.3 32.5,30.3" style="fill:currentColor;stroke:none"/><line x1="35.4" y1="138" x2="35.4" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="35.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="208.7" y1="138" x2="208.7" y2="142" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="34" x2="208.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3