('7bfff5cf-a820-586e-876c-1a98ef5ece37', '4914f17d-9839-51cb-b46f-531c50fdc962', 'Both give the same mean power', 'B', false, 1),
('5b93c58d-d63f-5211-b367-f6cbf280ac79', '4914f17d-9839-51cb-b46f-531c50fdc962', 'The d.c. supply gives twice the mean power', 'C', true, 2),
('800b801c-51b2-5bf9-8307-315305102527', '4914f17d-9839-51cb-b46f-531c50fdc962', 'The a.c. supply gives √2 times the mean power', 'D', false, 3),
('ea9f15a2-1629-57af-96cd-4f69cf9932dd', '45e708ae-745a-5be8-8ae6-757e3602318c', 'The r.m.s. voltage doubles and the mean power quadruples', 'A', true, 0),
('286f3d2a-8139-593e-8bcf-854005aa38a7', '45e708ae-745a-5be8-8ae6-757e3602318c', 'Both double', 'B', false, 1),
('7da60ce4-e9d2-565d-a2fc-7afc7e7df9bc', '45e708ae-745a-5be8-8ae6-757e3602318c', 'The r.m.s. voltage doubles and the power is unchanged', 'C', false, 2),
('ac532301-9c4e-5d42-b8ac-e7bc596057d7', '45e708ae-745a-5be8-8ae6-757e3602318c', 'Both quadruple', 'D', false, 3),
('8d8f06a9-9798-5aa5-b142-0044149f81c5', 'aca0ee51-f65f-5677-a436-0b8f350b207f', 'The current is never really negative', 'A', false, 0),
('8760f007-aadf-5409-a11a-47a9b80fcc19', 'aca0ee51-f65f-5677-a436-0b8f350b207f', 'Only the positive half cycles heat the resistor', 'B', false, 1),
('3511bd27-8088-5182-97ce-cbec1ff11256', 'aca0ee51-f65f-5677-a436-0b8f350b207f', 'The heating depends on the mean current', 'C', false, 2),
('084663f1-a23e-58a3-b95b-7b65d9f331c2', 'aca0ee51-f65f-5677-a436-0b8f350b207f', 'Heating depends on I², which is positive for either direction of current', 'D', true, 3),
('3ad6d5cf-e391-5eb7-bd14-4ac7bbbcc155', '3cb0736b-0253-5683-82d3-c6a3bfe6c2da', 'It is a sine curve between −I₀² and +I₀²', 'A', false, 0),
('d5b38cb6-af29-5bd9-8152-dbc5a6d38f06', '3cb0736b-0253-5683-82d3-c6a3bfe6c2da', 'It oscillates between 0 and I₀² at twice the supply frequency, with a mean of I₀²/2', 'B', true, 1),
('c3312579-f812-5694-b28b-0eb4d78a86ca', '3cb0736b-0253-5683-82d3-c6a3bfe6c2da', 'It is constant at I₀²', 'C', false, 2),
('b88cb07c-b54b-5e3d-864d-f09cb3ffe62f', '3cb0736b-0253-5683-82d3-c6a3bfe6c2da', 'It oscillates between 0 and I₀² at the supply frequency with mean I₀²', 'D', false, 3),
('bc3e4045-0d6f-5a63-96e3-4e01d86e4d2c', '8cbc702f-eda1-5be0-93fe-984a99c944c5', 'The peak voltage', 'A', false, 0),
('2d1b16fd-f690-5301-b141-c8d048ac41b8', '8cbc702f-eda1-5be0-93fe-984a99c944c5', 'The peak-to-peak voltage', 'B', false, 1),
('b04c1a54-b3d8-5245-81ce-bb2bfc4523a3', '8cbc702f-eda1-5be0-93fe-984a99c944c5', 'The r.m.s. voltage', 'C', true, 2),
('03028e5a-c393-5b0b-898c-b4bfd701a29e', '8cbc702f-eda1-5be0-93fe-984a99c944c5', 'The mean voltage', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('3c9bc4e1-42e1-50e8-be8a-6e6fe70ceebf', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 7, 7, 'Calculate the angular frequency of a 50 Hz supply.', NULL, 1, 'numeric'::answer_type, '314.2', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2πf = 2π × 50 = 314 rad s⁻¹. Mark scheme (2 marks). C1: ω = 2πf. A1: ω = 314 rad s⁻¹.', 2, NULL, NULL),
('8d1f6df7-5457-5782-922d-483f172027ea', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 8, 8, 'In the equation V = V₀ sin ωt, what does V₀ represent?', NULL, 1, 'multiple_choice'::answer_type, 'The peak voltage', NULL, false, NULL, false, NULL, 'V₀ is the largest value reached in each cycle. Mark scheme (1 mark). B1: C (The peak voltage).', 1, NULL, NULL),
('380ce4d2-986d-5d76-bc79-9cf089a25744', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 9, 9, 'An alternating voltage has ω = 100π rad s⁻¹. Calculate its period.', NULL, 1, 'numeric'::answer_type, '0.02', 's', false, NULL, false, NULL, 'T = 2π/ω = 2π ÷ 100π = 0.020 s. Mark scheme (2 marks). C1: T = 2π/ω. A1: T = 0.020 s.', 2, NULL, NULL),
('c66c9315-0d67-5479-b074-1741758d405a', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 10, 10, 'An oscilloscope trace has a peak 2.5 divisions above the centre line, with the Y-gain at 2.0 V per division. Calculate the peak voltage.', NULL, 1, 'numeric'::answer_type, '5', 'V', false, NULL, false, NULL, 'V₀ = 2.5 × 2.0 = 5.0 V. Mark scheme (2 marks). C1: divisions × Y-gain. A1: V₀ = 5.0 V.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 318" role="img" aria-labelledby="fga8b8d2f3-t fga8b8d2f3-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fga8b8d2f3-t">Oscilloscope trace</title><desc id="fga8b8d2f3-d">An oscilloscope screen with a grid of divisions. A sine wave has its peaks 2.5 divisions above the centre line. Y-gain 2.0 V per division.</desc><rect x="20" y="12" width="340" height="272" rx="6" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="54" y1="12" x2="54" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88" y1="12" x2="88" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="12" x2="122" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="156" y1="12" x2="156" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="12" x2="190" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="224" y1="12" x2="224" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stro