('9b8aa758-b0c4-5af8-b45a-2daa344425ae', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 27, 27, 'A 12 V r.m.s. sinusoidal supply is to be displayed on an oscilloscope. Calculate its peak-to-peak voltage, which must fit on the screen.', NULL, 2, 'numeric'::answer_type, '33.94', 'V', false, NULL, false, NULL, 'V_pp = 2√2 × V_rms = 2 × √2 × 12 = 33.9 V. Mark scheme (3 marks). C1: V₀ = √2 V_rms. C1: × 2. A1: V_pp = 33.9 V.', 3, NULL, NULL),
('13817840-13e1-5fee-ad2c-d86fe30df118', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 28, 28, 'For a sinusoidal supply connected across a resistor, what is the phase difference between the current and the voltage?', NULL, 2, 'multiple_choice'::answer_type, 'Zero: they reach their peaks together', NULL, false, NULL, false, NULL, 'I = V/R at every instant. Mark scheme (3 marks). C1: I ∝ V. C1: in phase. A1: C (Zero: they reach their peaks together).', 3, NULL, NULL),
('6b62ea45-6f25-5dcb-96dc-11b739b05d8d', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 29, 29, 'What is the frequency of a signal described by V = 5.0 sin(2000t), with t in seconds?', NULL, 2, 'numeric'::answer_type, '318.3', 'Hz', false, NULL, false, NULL, 'f = ω/2π = 2000 ÷ 2π = 318 Hz. Mark scheme (3 marks). C1: ω = 2000 rad s⁻¹. C1: f = ω/2π. A1: f = 318 Hz.', 3, NULL, NULL),
('ce334555-6624-56c1-b9be-b6e23073a218', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 30, 30, 'Calculate the time between successive peaks of a 60 Hz supply, in ms.', NULL, 2, 'numeric'::answer_type, '16.67 ms', 'ms', false, NULL, false, NULL, 'T = 1/f = 1 ÷ 60 = 0.0167 s. In ms: 0.01667 × 1000 = 16.7. Mark scheme (3 marks). C1: T = 1/f. C1: conversion. A1: T = 16.7 ms.', 3, NULL, NULL),
('a872c8de-39b5-5947-acbd-1a6cd825cdcf', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 31, 31, 'The time-base of an oscilloscope is changed from 5 ms per division to 2 ms per division. What happens to a steady sinusoidal trace?', NULL, 2, 'multiple_choice'::answer_type, 'Each cycle spreads over more divisions, so fewer cycles are visible', NULL, false, NULL, false, NULL, 'Each division now represents less time. Mark scheme (3 marks). C1: less time per division. C1: cycles spread out. A1: A (Each cycle spreads over more divisions, so fewer cycles are visible).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 318" role="img" aria-labelledby="fg0dda58a0-t fg0dda58a0-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg0dda58a0-t">Oscilloscope trace before the change</title><desc id="fg0dda58a0-d">An oscilloscope screen showing a steady sine wave with one cycle spanning 4 divisions, so two and a half cycles are visible, with the time-base at 5 ms per division (the setting before the change).</desc><rect x="20" y="12" width="340" height="272" rx="6" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="54" y1="12" x2="54" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88" y1="12" x2="88" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="12" x2="122" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="156" y1="12" x2="156" y2="284" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="12" x2="190"