('e2bba465-90f7-5fbd-98f4-852ddccfa1a6', '5810ca41-104e-5861-bc4a-6a1f8ab63746', '180°', 'C', false, 2),
('3e602f06-f060-5f26-a696-6d72eb5496c1', '5810ca41-104e-5861-bc4a-6a1f8ab63746', '360°', 'D', false, 3),
('b21f109d-23a5-599b-b1f8-18405511bc49', '13817840-13e1-5fee-ad2c-d86fe30df118', '90°', 'A', false, 0),
('ed81f02e-e11c-5db9-b3fd-1ebcb7f4d1e4', '13817840-13e1-5fee-ad2c-d86fe30df118', '180°', 'B', false, 1),
('9b497e78-74aa-5161-bc29-155671ee1ca5', '13817840-13e1-5fee-ad2c-d86fe30df118', 'Zero: they reach their peaks together', 'C', true, 2),
