('d9546b30-9d75-50c2-b5bd-a28e691b7ea5', 'a872c8de-39b5-5947-acbd-1a6cd825cdcf', 'More cycles are visible', 'B', false, 1),
('683d4fed-e154-5d2a-a147-7c5d6a1bb80f', 'a872c8de-39b5-5947-acbd-1a6cd825cdcf', 'The trace becomes taller', 'C', false, 2),
('7f3f4064-16d6-5f62-a6e2-8ad703b8a9f6', 'a872c8de-39b5-5947-acbd-1a6cd825cdcf', 'The trace becomes a straight line', 'D', false, 3),
('428e63a9-1633-5682-a1c2-2d959b03a0af', '58f787d9-61aa-54b3-9409-b4b145007352', 'V = 230 sin(314t)', 'A', false, 0),
('e4634b4f-d7c4-592d-8f8d-1b5582e5b44d', '58f787d9-61aa-54b3-9409-b4b145007352', 'V = 325 sin(50t)', 'B', false, 1),
('e26bf18c-5b4d-505f-9df7-39fea3193606', '58f787d9-61aa-54b3-9409-b4b145007352', 'V = 230 sin(50t)', 'C', false, 2),
('4c94a0e9-1d9d-5793-8b59-1657c00cee25', '58f787d9-61aa-54b3-9409-b4b145007352', 'V = 325 sin(314t)', 'D', true, 3),
