('9f5cc900-3452-58cc-891b-43202a64d6dd', '7e0b5a54-01ee-53f1-a05c-0d8571300462', 'A vertical line whose length is the peak-to-peak voltage', 'B', true, 1),
('ea4ccead-8359-5506-8136-9ffcccdd27f8', '7e0b5a54-01ee-53f1-a05c-0d8571300462', 'A single dot at the centre', 'C', false, 2),
('b3458c9e-c84b-51c5-bef8-78313b0a94be', '7e0b5a54-01ee-53f1-a05c-0d8571300462', 'A sine wave', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('2f6c974e-4c7c-53cb-8320-c9dbc64b52ef', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 7, 7, 'A lamp on a 120 V r.m.s. supply carries an r.m.s. current of 0.50 A. Calculate its mean power.', NULL, 1, 'numeric'::answer_type, '60', 'W', false, NULL, false, NULL, 'P = V_rms I_rms = 120 × 0.50 = 60 W. Mark scheme (2 marks). C1: P = V_rms I_rms. A1: P = 60 W.', 2, NULL, NULL),
('a470bb24-26ca-503a-af48-ed803041b14b', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 8, 8, 'For a resistor on a sinusoidal supply, how is the mean power related to the peak power?', NULL, 1, 'multiple_choice'::answer_type, 'Mean power = ½ × peak power', NULL, false, NULL, false, NULL, 'P = P₀ sin² ωt has a mean of P₀/2. Mark scheme (1 mark). B1: C (Mean power = ½ × peak power).', 1, NULL, NULL),
('7a2fe1ad-59ee-53fc-acc8-7c0d2b927053', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 9, 9, 'A resistor dissipates a mean power of 100 W on a sinusoidal supply. What is the peak power?', NULL, 1, 'numeric'::answer_type, '200', 'W', false, NULL, false, NULL, 'P₀ = 2 × 100 = 200 W. Mark scheme (2 marks). C1: peak = 2 × mean. A1: P₀ = 200 W.', 2, NULL, NULL),
('a8b30a0f-be0a-5891-b487-76dbf1291cd4', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 10, 10, 'A 60 W lamp runs on a 230 V r.m.s. supply. Calculate the r.m.s. current.', NULL, 1, 'numeric'::answer_type, '0.2609', 'A', false, NULL, false, NULL, 'I = P/V = 60 ÷ 230 = 0.261 A. Mark scheme (2 marks). C1: I = P/V. A1: I = 0.261 A.', 2, NULL, NULL),
('31f960c8-6eac-5297-8016-e80efec498d5', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 11, 11, 'Which expression gives the mean power in a resistor R on a supply of r.m.s. voltage V_rms?', NULL, 1, 'multiple_choice'::answer_type, 'V_rms²/R', NULL, false, NULL, false, NULL, 'Using r.m.s. values, a.c. power formulas look like d.c. ones. Mark scheme (1 mark). B1: A (V_rms²/R).', 1, NULL, NULL),
('aada65b1-2bbf-5796-b2d7-8bbfb53f6968', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 12, 12, 'A 2.0 kW heater runs on a 230 V r.m.s. supply. Calculate its resistance.', NULL, 1, 'numeric'::answer_type, '26.45', 'Ω', false, NULL, false, NULL, 'R = V²/P = 230² ÷ 2000 = 26.4 Ω. Mark scheme (2 marks). C1: R = V_rms²/P. A1: R = 26.4 Ω.', 2, NULL, NULL),
('65d870bf-b4b7-546a-be73-6c17f827d132', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 13, 13, 'Can the instantaneous power dissipated in a resistor on an a.c. supply be negative?', NULL, 1, 'multiple_choice'::answer_type, 'No: P = I²R is never negative', NULL, false, NULL, false, NULL, 'Energy is always transferred to the resistor. Mark scheme (1 mark). B1: D (No: P = I²R is never negative).', 1, NULL, NULL),
('038b2d82-39c0-5308-9fa8-8d5bd24dd970', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 14, 14, 'A 2.0 kW heater runs for 1.5 hours. Calculate the energy used, in kW h.', NULL, 1, 'numeric'::answer_type, '3', 'kW h', false, NULL, false, NULL, 'E = Pt in kW and hours: 2.0 × 1.5 = 3.0 kW h. Mark scheme (2 marks). C1: E = Pt in kW and h. A1: E = 3.0 kW h.', 2, NULL, NULL),
('74af1784-8223-502e-846d-ca03d9d7299f', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 15, 15, 'Why are mains voltages and currents usually quoted as r.m.s. values?', NULL, 1, 'multiple_choice'::answer_type, 'Because r.m.s. values give the same heating effect as equal d.c. values, so power calculations are simple', NULL, false, NULL, false, NULL, 'P = V_rms I_rms, just like P = VI for d.c. Mark scheme (1 mark). B1: B (Because r.m.s. values give the same heating effect as equal d.c. values, so power calculations are simple).', 1, NULL, NULL),
('7ec364eb-d69e-5713-bb8c-49124ee54436', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 16, 16, 'A sinusoidal current of peak 4.0 A flows in a 5.0 Ω resistor. Calculate the mean power.', NULL, 1, 'numeric'::answer_type, '40', 'W', false, NULL, false, NULL, 'P = ½I₀²R = 0.5 × 4.0² × 5.0 = 40 W. Mark scheme (2 marks). C1: ½I₀²R. A1: P = 40 W.', 2, NULL, NULL),
('90d56171-ac0c-56eb-83f7-632208ce47a2', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 17, 17, 'The r.m.s. voltage across a resistor is doubled. What happens to the mean power?', NULL, 1, 'multiple_choice'::answer_type, 'It quadruples', NULL, false, NULL, false, NULL, 'P = V_rms²/R, so doubling V_rms makes the power four times larger. Mark scheme (1 mark). B1: C (It quadruples).', 1, NULL, NULL),
('278b369c-910e-5c31-a87c-1d291106b04b', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 18, 18, 'How many joules does a 500 W food mixer use in a 10-minute run?', NULL, 1, 'numeric'::answer_type, '3e5', 'J', false, NULL, false, NULL, 'E = Pt = 500 × 600 = 3.0 × 10⁵ J. Mark scheme (2 marks). C1: t in seconds. A1: E = 3.0 × 10⁵ J.', 2, NULL, NULL),
('6445c049-0943-5f12-98d0-e0106e9bfb6d', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 19, 19, 'What is the peak power dissipated in a resistor carrying a sinusoidal current of peak I₀ at peak voltage V₀?', NULL, 1, 'multiple_choice'::answer_type, 'V₀I₀', NULL, false, NULL, false, NULL, 'At the peak of the cycle, P = V₀I₀. Mark scheme (1 mark). B1: A (V₀I₀).', 1, NULL, NULL),
('818a235f-873b-5e36-903e-3f16f445ba92', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 20, 20, 'A resistor is moved from a 115 V r.m.s. supply to a 230 V r.m.s. supply. By what factor does its mean power increase?', NULL, 1, 'numeric'::answer_type, '4', NULL, false, NULL, false, NULL, 'P ∝ V²: (230 ÷ 115)² = 4.0. Mark scheme (1 mark). A1: factor = 4.0.', 1, NULL, NULL),
('d0814805-6273-5889-8993-8c05687e704d', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 21, 21, 'A fuse is chosen for an appliance on an a.c. supply. Which current is used to choose it?', NULL, 1, 'multiple_choice'::answer_type, 'The r.m.s. current', NULL, false, NULL, false, NULL, 'A fuse melts because of heating, which depends on I_rms. Mark scheme (1 mark). B1: D (The r.m.s. current).', 1, NULL, NULL),
('204cd0ec-529d-5f6e-8b4a-1a038283bf91', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 22, 22, 'Calculate the r.m.s. voltage needed to give a mean power of 100 W in a 25 Ω resistor.', NULL, 1, 'numeric'::answer_type, '50', 'V', false, NULL, false, NULL, 'V_rms = √(PR) = √(100 × 25) = 50 V. Mark scheme (2 marks). C1: rearranged. A1: V_rms = 50 V.', 2, NULL, NULL),
('7edf0532-c8f9-5c20-a810-d576592cd1cb', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 23, 23, 'For a resistor on a 50 Hz sinusoidal supply, how does the instantaneous power vary?', NULL, 1, 'multiple_choice'::answer_type, 'It rises and falls between zero and a maximum 100 times each second', NULL, false, NULL, false, NULL, 'P ∝ sin² ωt, which has twice the supply frequency. Mark scheme (1 mark). B1: B (It rises and falls between zero and a maximum 100 times each second).', 1, NULL, NULL),
('6c125fda-ef5d-5659-b74c-66357f86392c', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 24, 24, 'A 3.0 kW kettle runs on a 230 V r.m.s. supply. Calculate the peak current.', NULL, 2, 'numeric'::answer_type, '18.45', 'A', false, NULL, false, NULL, 'I_rms = 3000 ÷ 230 = 13.0 A. I₀ = √2 × 13.04 = 18.4 A. Mark scheme (3 marks). C1: I_rms = P/V. C1: × √2. A1: I₀ = 18.4 A.', 3, NULL, NULL),
('804fb39d-e641-541a-97e3-94aa6f9ae2b5', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 25, 25, 'A 2.5 kW oven is used for 3.0 hours. Calculate the energy used, in kW h.', NULL, 2, 'numeric'::answer_type, '7.5', 'kW h', false, NULL, false, NULL, 'E = Pt = 2.5 × 3.0 = 7.5 kW h. Mark scheme (3 marks). C1: kW × h. C1: value. A1: E = 7.5 kW h.', 3, NULL, NULL),
('d181bb3c-7fb3-5582-9067-60bb880efe79', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 26, 26, 'A resistor is connected to a 50 Hz sinusoidal supply. Calculate the frequency at which the instantaneous power oscillates.', NULL, 2, 'numeric'::answer_type, '100', 'Hz', false, NULL, false, NULL, 'P ∝ sin² ωt = ½(1 − cos 2ωt): frequency = 2 × 50 = 100 Hz. Mark scheme (3 marks). M1: sin² doubles frequency. C1: value. A1: f = 100 Hz.', 3, NULL, NULL),
('87c4778f-930b-57d9-9723-7f681e24a1df', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 27, 27, 'A 12 V, 24 W lamp (rated for 12 V d.c.) is connected to a sinusoidal supply of peak 12 V. Assuming its resistance is constant, calculate its mean power.', NULL, 2, 'numeric'::answer_type, '12', 'W', false, NULL, false, NULL, 'R = 12² ÷ 24 = 6.0 Ω. V_rms = 12 ÷ √2, so P = (12 ÷ √2)² ÷ 6.0 = 72 ÷ 6.0 = 12 W. Mark scheme (4 marks). C1: R from rating. C1: V_rms. C1: P = V_rms²/R. A1: P = 12 W.', 4, NULL, NULL),
('cf943491-7249-535e-8629-34160917d648', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 28, 28, 'A resistive load has a peak voltage of 340 V across it and a peak current of 1.5 A. Calculate the mean power.', NULL, 2, 'numeric'::answer_type, '255', 'W', false, NULL, false, NULL, 'P = ½V₀I₀ = 0.5 × 340 × 1.5 = 255 W. Mark scheme (3 marks). C1: ½V₀I₀. C1: value. A1: P = 255 W.', 3, NULL, NULL),
('76dc6bd6-18cc-5054-abfe-8ecae996a2c4', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 29, 29, 'A resistor is connected first to a 6.0 V d.c. supply and then to a 6.0 V r.m.s. a.c. supply. How do the mean powers compare?', NULL, 2, 'multiple_choice'::answer_type, 'They are equal', NULL, false, NULL, false, NULL, 'By definition, the r.m.s. value gives the same heating as the equal d.c. value. Mark scheme (3 marks). C1: definition of r.m.s. C1: equal power. A1: C (They are equal).', 3, NULL, NULL),
('0ab96a26-5aaa-58ac-9396-5b6c5f3a5086', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 30, 30, 'On a 115 V r.m.s. supply, what r.m.s. current does a 690 W microwave oven draw?', NULL, 2, 'numeric'::answer_type, '6', 'A', false, NULL, false, NULL, 'I = P/V = 690 ÷ 115 = 6.0 A. Mark scheme (3 marks). C1: I = P/V. C1: value. A1: I = 6.0 A.', 3, NULL, NULL),
('d15e4c1a-8858-5622-9ca8-d58ee47bfbd9', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 31, 31, 'A lamp takes a mean power of 60 W from a 50 Hz supply. Calculate the energy it receives during one cycle.', NULL, 2, 'numeric'::answer_type, '1.2', 'J', false, NULL, false, NULL, 'E = P × T = 60 × (1 ÷ 50) = 1.2 J. Mark scheme (4 marks). C1: T = 1/f. M1: E = P_mean × T. C1: value. A1: E = 1.2 J.', 4, NULL, NULL),
('d9893fd9-0d9d-5247-8fd7-da57dc9b1939', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 32, 32, 'Both the r.m.s. voltage across a resistor and its resistance are doubled. What happens to the mean power?', NULL, 2, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'P = V²/R: (2²)/2 = 2. Mark scheme (3 marks). C1: P = V²/R. C1: factor 4 ÷ 2. A1: A (It doubles).', 3, NULL, NULL),
('46792295-3a6e-5e06-b99a-acb68d33fdf1', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 33, 33, 'A resistor has a peak p.d. of 17 V across it and a peak current of 0.50 A. Calculate its resistance.', NULL, 2, 'numeric'::answer_type, '34', 'Ω', false, NULL, false, NULL, 'R = V₀/I₀ = 17 ÷ 0.50 = 34 Ω. Mark scheme (3 marks). C1: R = V/I with peak or r.m.s. values. C1: value. A1: R = 34 Ω.', 3, NULL, NULL),
('19ce5895-e39b-5d07-b9ed-2d7575eb36fa', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 34, 34, 'A 40 Ω heater and a 6.0 Ω cable resistance are in series on a 230 V r.m.s. supply. Calculate the mean power in the heater.', NULL, 2, 'numeric'::answer_type, '1000', 'W', false, NULL, false, NULL, 'I = 230 ÷ (40 + 6.0) = 5.0 A. P = I²R = 5.0² × 40 = 1000 W. Mark scheme (3 marks). C1: series current. C1: P = I²R. A1: P = 1000 W.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 182" role="img" aria-labelledby="fg72384a34-t fg72384a34-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg72384a34-t">Heater and cable</title><desc id="fg72384a34-d">Circuit: a 230 V r.m.s. a.c. supply in series with the cable resistance of 6.0 Ω and a 40 Ω heater.</desc><line x1="26" y1="48" x2="68.2" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="104.2" y1="48" x2="146.4" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="68.2" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="86.2" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">cable 6.0 Ω</text><line x1="146.4" y1="48" x2="192.2" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="228.2" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="192.2" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="210.2" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">heater 40 Ω</text><line x1="26" y1="142" x2="138" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="162" y1="142" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="150" cy="142" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M143,142 q3.5,-7 7,0 t7,0" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="166" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">230 V r.m.s.</text><line x1="26" y1="48" x2="26" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Circuit: a 230 V r.m.s. a.c. supply in series with the cable resistance of 6.0 Ω and a 40 Ω heater.'),
('b53be78b-81fa-5b17-83dc-b671dacfcb94', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 35, 35, 'Why are cables rated by their maximum r.m.s. current?', NULL, 2, 'multiple_choice'::answer_type, 'The heating of the cable depends on the mean of I², which is I_rms²', NULL, false, NULL, false, NULL, 'Overheating damages insulation; P = I_rms²R. Mark scheme (4 marks). C1: heating ∝ I². C1: mean of I² = I_rms². C1: insulation limit. A1: D (The heating of the cable depends on the mean of I², which is I_rms²).', 4, NULL, NULL),
('15572418-7dce-5a23-b13b-1c2a98490161', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 36, 36, 'A 9.0 kW electric shower runs for 8.0 minutes. Calculate the energy used, in MJ.', NULL, 2, 'numeric'::answer_type, '4.32 MJ', 'MJ', false, NULL, false, NULL, 'E = 9.0 × 10³ × 480 = 4.32 × 10⁶ J. In MJ: 4.32 × 10⁶ ÷ 10⁶ = 4.32. Mark scheme (3 marks). C1: t in s. C1: conversion. A1: E = 4.32 MJ.', 3, NULL, NULL),
('fcb0e1bd-79cd-5cb9-9572-0249ff82da88', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 37, 37, 'An appliance takes a mean power of 2.3 kW from a sinusoidal supply. Calculate the peak power, in kW.', NULL, 2, 'numeric'::answer_type, '4.6 kW', 'kW', false, NULL, false, NULL, 'P₀ = 2 × P_mean = 2 × 2.3 = 4.6 kW. Mark scheme (4 marks). M1: P₀ = I₀V₀ = 2I_rmsV_rms. C1: factor 2. C1: value. A1: P₀ = 4.6 kW.', 4, NULL, NULL),
('f9756b49-e3a2-5170-8620-00c736f06893', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 38, 38, 'How many joules are there in 1 kW h?', NULL, 2, 'multiple_choice'::answer_type, '3.6 × 10⁶ J', NULL, false, NULL, false, NULL, '1 kW h = 1000 W × 3600 s. Mark scheme (3 marks). C1: kW to W. C1: h to s. A1: B (3.6 × 10⁶ J).', 3, NULL, NULL),
('ee629949-c5be-51ad-ab2a-3a1720c336d2', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 39, 39, 'A 60 W lamp runs on a 230 V r.m.s. supply. Calculate the largest instantaneous current in it.', NULL, 2, 'numeric'::answer_type, '0.3689', 'A', false, NULL, false, NULL, 'I_rms = 60 ÷ 230 = 0.261 A. I₀ = √2 × 0.2609 = 0.369 A. Mark scheme (3 marks). C1: I_rms. C1: × √2. A1: I₀ = 0.369 A.', 3, NULL, NULL),
('271b160f-e259-540d-a7e5-72cca171e8b4', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 40, 40, 'A heater gives 1.2 kW on a 230 V r.m.s. supply. Calculate its power, in W, when the supply falls to 207 V r.m.s., assuming constant resistance.', NULL, 2, 'numeric'::answer_type, '972', 'W', false, NULL, false, NULL, 'P ∝ V²: P = 1200 × (207 ÷ 230)² = 972 W. Mark scheme (3 marks). C1: P ∝ V². C1: value. A1: P = 972 W.', 3, NULL, NULL),
('28fabbaf-02f7-572d-a91b-fdf9d40de7c9', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 41, 41, 'A 3.0 kW heater runs on a 230 V r.m.s. supply. (a) Calculate the r.m.s. current. (b) Calculate the resistance. (c) Calculate the peak current and the peak power. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '17.63', 'Ω', false, NULL, false, NULL, '(a) I_rms = 3000 ÷ 230 = 13.0 A. (b) R = V²/P = 230² ÷ 3000 = 17.6 Ω. (c) I₀ = √2 × 13.04 = 18.4 A; P₀ = 2 × 3.0 = 6.0 kW. Mark scheme (5 marks). C1: I_rms. C1: R. C1: I₀. C1: P₀ = 2P. A1: R = 17.6 Ω.', 5, NULL, NULL),
('738722dc-5dfb-5846-8bc1-1c44960ef294', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 42, 42, 'A current of 5.0 A flows through a 20 Ω resistor for 0.30 of each cycle and is zero for the rest. (a) Calculate the mean power. (b) Calculate the r.m.s. current. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '150', 'W', false, NULL, false, NULL, '(a) While on, P = 5.0² × 20 = 500 W; mean = 0.30 × 500 = 150 W. (b) I_rms = √(0.30 × 5.0²) = 2.74 A; check I_rms² × 20 = 150 W. Mark scheme (5 marks). C1: power while on. M1: × fraction of time. C1: value. C1: I_rms. A1: P = 150 W.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg48f0fa79-t fg48f0fa79-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg48f0fa79-t">Pulsed current</title><desc id="fg48f0fa79-d">Graph of current against time t: 5.0 A for the first 0.30 of each period T and zero for the remaining 0.70 of the period. Two periods are shown.</desc><line x1="33" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="33" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="33,24 36,30.3 30.1,30.3" style="fill:currentColor;stroke:none"/><line x1="33" y1="242" x2="33" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="33" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="85.4" y1="242" x2="85.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;