('acae83cf-1078-5450-a6b9-ace98c95bb59', '65d870bf-b4b7-546a-be73-6c17f827d132', 'Yes, at the peak of each cycle', 'B', false, 1),
('eaf77919-0fa0-5fec-beb6-6457e9f9919d', '65d870bf-b4b7-546a-be73-6c17f827d132', 'Only when the frequency is high', 'C', false, 2),
('b3cbaea4-d6e9-5de2-8336-d3e35c1de6ff', '65d870bf-b4b7-546a-be73-6c17f827d132', 'No: P = I²R is never negative', 'D', true, 3),
('280d60b8-f0fd-584c-96b8-48ba861a80b9', '74af1784-8223-502e-846d-ca03d9d7299f', 'Because they are the largest values', 'A', false, 0),
('03834e25-399a-58fe-95ca-2ed25309ccc8', '74af1784-8223-502e-846d-ca03d9d7299f', 'Because r.m.s. values give the same heating effect as equal d.c. values, so power calculations are simple', 'B', true, 1),
('9973d988-5286-57bc-aa7c-d6ac29416bb3', '74af1784-8223-502e-846d-ca03d9d7299f', 'Because they are the peak values', 'C', false, 2),
('710c2706-fec1-52aa-b287-41564bb017d9', '74af1784-8223-502e-846d-ca03d9d7299f', 'Because the mean values are always zero', 'D', false, 3),
