('24524053-b746-5ae9-9df3-c6928057c16d', '6445c049-0943-5f12-98d0-e0106e9bfb6d', 'V₀I₀/√2', 'C', false, 2),
('5ca3b1ff-8530-503f-8d2f-1d62736bf715', '6445c049-0943-5f12-98d0-e0106e9bfb6d', '2V₀I₀', 'D', false, 3),
