('5ddf054a-d5d3-58d9-af25-376f1e4fe9e2', 'd0814805-6273-5889-8993-8c05687e704d', 'The r.m.s. current', 'D', true, 3),
('586e804c-23b6-5da6-ae53-6f68e98b97c5', '7edf0532-c8f9-5c20-a810-d576592cd1cb', 'It is constant', 'A', false, 0),
('99fd42ba-6107-57ad-84f5-229838a56f09', '7edf0532-c8f9-5c20-a810-d576592cd1cb', 'It rises and falls between zero and a maximum 100 times each second', 'B', true, 1),
('2b9d935e-9274-5466-8e40-b933fe0e1c3e', '7edf0532-c8f9-5c20-a810-d576592cd1cb', 'It reverses direction 100 times a second', 'C', false, 2),
