INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('53482893-8f88-5f75-9c70-260d2459e4e8', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 9, 9, 'What does the output of a half-wave rectifier look like?', NULL, 1, 'multiple_choice'::answer_type, 'Only the positive half cycles; the negative half cycles are removed', NULL, false, NULL, false, NULL, 'A single diode conducts in one direction only. Mark scheme (1 mark). B1: C (Only the positive half cycles; the negative half cycles are removed).', 1, NULL, NULL),
('285f433c-38f4-5054-9760-b2e115a7b1e3', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 10, 10, 'What does the output of a full-wave bridge rectifier look like?', NULL, 1, 'multiple_choice'::answer_type, 'A series of positive humps: the negative half cycles are turned positive', NULL, false, NULL, false, NULL, 'Four diodes route both halves of the cycle the same way through the load. Mark scheme (1 mark). B1: A (A series of positive humps: the negative half cycles are turned positive).', 1, NULL, NULL),
('64417728-7f67-52d0-b119-60f0e66f049f', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 11, 11, 'A 50 Hz supply is full-wave rectified. Calculate the time between successive peaks of the output.', NULL, 1, 'numeric'::answer_type, '0.01', 's', false, NULL, false, NULL, 'There are 2 × 50 = 100 peaks per second, so the time between peaks = 1 ÷ 100 = 0.010 s. Mark scheme (2 marks). C1: two peaks per cycle. A1: t = 0.010 s.', 2, NULL, NULL),
('cdf41919-50b4-52ac-aefc-98dd76a34d25', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 12, 12, 'A 1000 µF smoothing capacitor is used with a 2.2 kΩ load. Calculate the time constant.', NULL, 1, 'numeric'::answer_type, '2.2', 's', false, NULL, false, NULL, 'τ = RC = 2.2 × 10³ × 1000 × 10⁻⁶ = 2.2 s. Mark scheme (2 marks). C1: τ = RC. A1: τ = 2.2 s.', 2, NULL, NULL),
('2ff58297-fcfe-54bc-be6c-175e7232ad1b', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 13, 13, 'Which property of a diode is used in a rectifier?', NULL, 1, 'multiple_choice'::answer_type, 'It conducts in only one direction', NULL, false, NULL, false, NULL, 'Current can flow forwards but not backwards through the diode. Mark scheme (1 mark). B1: D (It conducts in only one direction).', 1, NULL, NULL),
('7706dce3-ed79-5ba1-908f-c78df0ab982e', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 14, 14, 'A transformer gives 12 V r.m.s. to a rectifier. Ignoring the diodes, calculate the peak output voltage.', NULL, 1, 'numeric'::answer_type, '16.97', 'V', false, NULL, false, NULL, 'V₀ = √2 × 12 = 17.0 V. Mark scheme (2 marks). C1: V₀ = √2 V_rms. A1: V₀ = 17.0 V.', 2, NULL, NULL),
('6eca75a2-a3c1-524b-b809-d19f9b150578', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 15, 15, 'A larger smoothing capacitor is used, with the same load. What happens to the ripple?', NULL, 1, 'multiple_choice'::answer_type, 'It decreases', NULL, false, NULL, false, NULL, 'A larger RC means the capacitor discharges less between peaks. Mark scheme (1 mark). B1: B (It decreases).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg48555f6a-t fg48555f6a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg48555f6a-t">Smoothed full-wave output</title><desc id="fg48555f6a-d">Graph of p.d. against time t. The dashed curve is the full-wave rectified p.d.; the solid curve is the smoothed output, which follows each peak and then falls slowly until the next peak, giving a ripple.</desc><line x1="28.7" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="28.7" y1="242" x2="28.7" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="28.7,24 31.7,30.3 25.8,30.3" style="fill:currentColor;stroke:none"/><line x1="28.7" y1="242" x2="28.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="28.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="137.4" y1="242" x2="137.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="137.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:cu