('6a04c172-7fe6-5718-b100-500f714713af', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 37, 37, 'For a smoothed full-wave rectifier on 50 Hz, the ripple must be about 2.0 % of the peak voltage. Using ΔV/V₀ ≈ t/RC, calculate the time constant needed.', NULL, 2, 'numeric'::answer_type, '0.5', 's', false, NULL, false, NULL, 'RC = t ÷ (ΔV/V₀) = 0.010 ÷ 0.020 = 0.50 s. Mark scheme (3 marks). C1: t = 0.010 s. C1: rearranged. A1: RC = 0.50 s.', 3, NULL, NULL),
('1ce10728-3de2-5866-a25c-cd045cf790fa', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 38, 38, 'A smoothing capacitor discharges through a load with RC = 0.20 s. Calculate the time for its p.d. to fall to 95 % of its peak, in ms.', NULL, 2, 'numeric'::answer_type, '10.26 ms', 'ms', false, NULL, false, NULL, 't = RC ln(1/0.95) = 0.20 × ln 1.0526 = 0.0103 s. In ms: 0.01026 × 1000 = 10.3. Mark scheme (3 marks). C1: logs. C1: conversion. A1: t = 10.3 ms.', 3, NULL, NULL),
('2ecf307a-6ab8-5b23-872b-163917903456', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 39, 39, 'Why does the smoothing capacitor''s p.d. rise only during a short part of each cycle?', NULL, 2, 'multiple_choice'::answer_type, 'The diodes conduct only when the rectified input is higher than the capacitor''s p.d.', NULL, false, NULL, false, NULL, 'Most of the time the diodes are reverse-biased. Mark scheme (3 marks). C1: diode forward-biased only near peaks. C1: capacitor discharges otherwise. A1: C (The diodes conduct only when the rectified input is higher than the capacitor''s p.d.).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg9395cab6-t fg9395cab6-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9395cab6-t">Smoothed output</title><desc id="fg9395cab6-d">Graph of p.d. against time t. The dashed curve is the full-wave rectified supply; the solid curve is the capacitor p.d., which rises only near each peak of the supply and falls slowly in between.</desc><line x1="28.7" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="28.7" y1="242" x2="28.7" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="28.7,24 31.7,30.3 25.8,30.3" style="fill:currentColor;stroke:none"/><line x1="28.7" y1="242" x2="28.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="28.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="170" y1="242" x2="170" y2="246" style="stroke